#!/usr/bin/env python3
"""Regenerate computed_gt.json for CSX-020_Q2."""

from __future__ import annotations

import json
import math
from collections import Counter
from pathlib import Path
from typing import Any


TASK_ID = "CSX-020_Q2"
EVENT_ID = "CSX-020"
OUTPUT_NAME = "computed_gt.json"
PACKAGE_RELATIVE_PATH = "event_packages/standard_event_packages/packages/CSX-020"



DEEPENED_TASK_FRAME = {'bounded_prompt': 'The package can diagnose local dry-heat stress but cannot estimate actual fire spread, burned '
                   'assets, or health outcomes.',
 'decisive_evidence_prompt': 'The strongest evidence is the combination of hot daytime load and dry-air stress, with '
                             'receptors treated as context rather than the trigger.',
 'group': 'deepened_remaining_39',
 'mechanism_chain': ['hot daytime forcing',
                     'dry-air or vapor-pressure stress',
                     'rainfall moderation check',
                     'exposure context'],
 'mechanism_question': 'test whether dry daytime heat and atmospheric dryness dominate the event instead of humid '
                       'heat, rainfall, or exposure-only context',
 'new_title': 'Black Summer Dry-Heat Fire-Weather Exposure Chain',
 'rejected_prompt': 'Reject humid-heat dominance, rainfall moderation, and exposure-only explanations when '
                    'meteorological forcing is stronger.',
 'target_family': 'compound_dry_heat_fire_weather_chain_diagnosis',
 'task_mode': 'deep_mechanism_diagnosis'}

def _deep_rename_key(key):
    replacements = [
        ("score_ledger", "evidence_rows"),
        ("ledger_rows", "evidence_rows"),
        ("ledger", "evidence_synthesis"),
        ("Ledger", "EvidenceSynthesis"),
        ("consistency", "process_alignment"),
        ("Consistency", "ProcessAlignment"),
        ("threshold", "diagnostic_gate"),
        ("Threshold", "DiagnosticGate"),
        ("gate", "diagnostic_test"),
        ("Gate", "DiagnosticTest"),
        ("score_breakdown", "evidence_score_breakdown"),
        ("score", "evidence_score"),
        ("Score", "EvidenceScore"),
    ]
    out = str(key)
    for old, new in replacements:
        out = out.replace(old, new)
    return out


def _deep_rename_obj(value, parent_key=None):
    protected_value_keys = {
        "answer",
        "final_label",
        "classification",
        "label",
        "diagnosis",
        "result",
        "answer_type",
        "task_family",
        "target_family",
    }
    if isinstance(value, dict):
        return {_deep_rename_key(k): _deep_rename_obj(v, k) for k, v in value.items()}
    if isinstance(value, list):
        return [_deep_rename_obj(v, parent_key) for v in value]
    if isinstance(value, str):
        if parent_key in protected_value_keys:
            return value
        out = value
        replacements = [
            ("ledger", "evidence synthesis"),
            ("Ledger", "Evidence synthesis"),
            ("consistency", "process alignment"),
            ("Consistency", "Process alignment"),
            ("threshold", "diagnostic gate"),
            ("Threshold", "Diagnostic gate"),
        ]
        for old, new in replacements:
            out = out.replace(old, new)
        return out
    return value

def _deep_extract_answer(value):
    if isinstance(value, dict):
        for key in ("final_label", "answer", "classification", "label", "final_interpretation", "diagnosis"):
            if key in value and isinstance(value[key], (str, int, float, bool)):
                return str(value[key])
        for key in ("classification", "threshold_result", "result"):
            if key in value and isinstance(value[key], dict):
                nested = _deep_extract_answer(value[key])
                if nested:
                    return nested
    return "deep_mechanism_diagnosis"


def apply_deepened_task_frame(result):
    frame = dict(DEEPENED_TASK_FRAME)
    old_primary = result.get("primary_gt")
    if not isinstance(old_primary, dict):
        old_primary = {"value": old_primary}
    transformed = {
        "answer": frame.get("answer_override", _deep_extract_answer(old_primary)),
        "task_mode": frame["task_mode"],
        "mechanism_question": frame["mechanism_question"],
        "computed_evidence": _deep_rename_obj(old_primary),
        "mechanism_chain": list(frame["mechanism_chain"]),
        "decisive_evidence": frame["decisive_evidence_prompt"],
        "rejected_simplifications": frame["rejected_prompt"],
        "bounded_interpretation": frame["bounded_prompt"],
    }
    if frame.get("formula_prompt"):
        transformed["formula_derivation"] = frame["formula_prompt"]
    if isinstance(transformed.get("computed_evidence"), dict):
        for stale_key in ("answer", "answer_type", "target_family", "task_family"):
            transformed["computed_evidence"].pop(stale_key, None)
    result["primary_gt"] = transformed
    result["task_type"] = "structured_reasoning"
    result["evaluation_mode"] = "hybrid"
    result["subtype"] = frame["task_mode"]
    result["target_family"] = frame.get("target_family", frame["task_mode"])
    result["deepened_reframe"] = {
        "group": frame["group"],
        "replaces_table_only_task": True,
        "new_title": frame["new_title"],
    }
    guidance = result.get("answer_guidance")
    if isinstance(guidance, dict):
        guidance["structured_answer"] = transformed
        guidance["answer"] = transformed["answer"]
    else:
        result["answer_guidance"] = {"structured_answer": transformed, "answer": transformed["answer"]}
    result["rubric"] = {
        "total_points": 20,
        "criteria": [
            {"name": "mechanism_diagnosis", "points": 4, "description": "Identifies the dominant physical process and gives the correct compact answer label or an equivalent diagnosis."},
            {"name": "computed_evidence", "points": 5, "description": "Recomputes the quantitative evidence inherited from the original task and preserves units, signs, ratios, and key values."},
            {"name": "evidence_weighting", "points": 4, "description": "Explains which evidence streams are decisive and which are contextual or weaker proxies."},
            {"name": "counterfactual_rejection", "points": 3, "description": "Rejects at least one tempting simplified explanation using the computed values rather than assertion."},
            {"name": "bounded_interpretation", "points": 2, "description": "States scale, timing, proxy, or uncertainty limits without adding unsupported losses or impacts."},
            {"name": "json_contract", "points": 2, "description": "Returns the requested structured mechanism-diagnosis JSON without reducing the answer to a row-only table or same-scale checklist."},
        ],
    }
    if frame.get("formula_prompt"):
        result["rubric"] = {
            "total_points": 20,
            "criteria": [
                {"name": "mechanism_diagnosis", "points": 3, "description": "Identifies the dominant physical process and gives the correct compact mechanism label or equivalent diagnosis."},
                {"name": "computed_evidence", "points": 4, "description": "Recomputes the package-derived quantitative evidence with correct units, signs, ratios, dates, and rounding."},
                {"name": "formula_derivation", "points": 3, "description": "Shows the requested physical formula, scaling relation, or timing relation and connects it to the computed values."},
                {"name": "evidence_weighting", "points": 3, "description": "Explains which evidence streams are decisive and which are contextual or weaker proxies."},
                {"name": "counterfactual_rejection", "points": 3, "description": "Rejects tempting simplified explanations using computed values rather than assertion."},
                {"name": "bounded_interpretation", "points": 2, "description": "States scale, timing, proxy, or uncertainty limits without adding unsupported losses or impacts."},
                {"name": "json_contract", "points": 2, "description": "Returns the requested structured mechanism-diagnosis JSON without reducing the answer to a row-only table."},
            ],
        }

    return result

def repo_root() -> Path:
    return Path(__file__).resolve().parents[3]


def package_dir() -> Path:
    return repo_root() / PACKAGE_RELATIVE_PATH


def load_json(rel_path: str) -> Any:
    return json.loads((package_dir() / rel_path).read_text(encoding="utf-8-sig"))


def saturation_vapor_pressure_kpa(temp_c: float) -> float:
    return 0.6108 * math.exp((17.27 * temp_c) / (temp_c + 237.3))


def vapor_pressure_deficit_kpa(temp_c: float, rh_percent: float) -> float:
    rh = max(0.0, min(100.0, rh_percent))
    return saturation_vapor_pressure_kpa(temp_c) * (1.0 - rh / 100.0)


def compute() -> dict[str, Any]:
    met_rel = "data/physical_hazard/physical_hazard_001_Open-Meteo_historical_archive.json"
    pop_rel = "data/exposure_impact/exposure_impact_004_WorldPop_GP_100m_population_sum.json"
    amenity_rel = "data/exposure_impact/exposure_impact_003_Overpass_small_roads_and_critical_amenities.json"
    event_rel = "metadata/event.json"

    event = load_json(event_rel)
    met = load_json(met_rel)
    daily = met["daily"]
    dates = daily["time"]
    tmax = [float(value) for value in daily["temperature_2m_max"]]
    tmin = [float(value) for value in daily["temperature_2m_min"]]

    hourly = met["hourly"]
    hourly_temp = [float(value) for value in hourly["temperature_2m"]]
    hourly_rh = [float(value) for value in hourly["relative_humidity_2m"]]
    vpds = [
        vapor_pressure_deficit_kpa(temp, rh)
        for temp, rh in zip(hourly_temp, hourly_rh)
    ]

    heat_load = round(sum(max(0.0, value - 35.0) for value in tmax), 1)
    warm_nights = sum(value >= 18.0 for value in tmin)
    peak_vpd = round(max(vpds), 2)
    hot_dry_hours = sum(
        temp >= 35.0 and rh <= 20.0
        for temp, rh in zip(hourly_temp, hourly_rh)
    )
    hot_humid_hours = sum(
        temp >= 35.0 and rh >= 50.0
        for temp, rh in zip(hourly_temp, hourly_rh)
    )

    population = int(round(float(load_json(pop_rel)["population_sum"]["population"])))
    amenities = load_json(amenity_rel).get("elements", [])
    amenity_counts = Counter(
        item.get("tags", {}).get("amenity")
        for item in amenities
        if item.get("tags", {}).get("amenity")
    )
    critical_amenities = sum(amenity_counts.values())

    thresholds = {
        "heat_load_c_days_gt35": 30.0,
        "warm_nights_ge18c": 3,
        "peak_vpd_kpa": 6.0,
        "hot_dry_hours": 24,
        "hot_humid_hours_max": 1,
        "population_min": 300000,
        "critical_amenities_min": 50,
    }
    tests = {
        "heat_load": heat_load >= thresholds["heat_load_c_days_gt35"],
        "warm_nights": warm_nights >= thresholds["warm_nights_ge18c"],
        "dry_air": peak_vpd >= thresholds["peak_vpd_kpa"],
        "hot_dry": hot_dry_hours >= thresholds["hot_dry_hours"],
        "humid_countercheck": hot_humid_hours <= thresholds["hot_humid_hours_max"],
        "exposure": (
            population >= thresholds["population_min"]
            and critical_amenities >= thresholds["critical_amenities_min"]
        ),
    }
    score = sum(1 for passed in tests.values() if passed)
    if score >= 5:
        label = "compound_dry_heat_fire_weather_exposure_supported"
    elif score >= 3:
        label = "partial_support"
    else:
        label = "not_supported"

    primary_gt = {
        "label": label,
        "score": score,
        "heat_load_c_days_gt35": heat_load,
        "warm_nights_ge18c": warm_nights,
        "dryness_ledger": {
            "peak_vpd_kpa": peak_vpd,
            "hot_dry_hours": int(hot_dry_hours),
            "hot_humid_hours": int(hot_humid_hours),
        },
        "exposure_ledger": {
            "population": population,
            "critical_amenities": int(critical_amenities),
        },
    }

    rubric = {
        "total_points": 20,
        "criteria": [
            {
                "name": "final_label_and_score",
                "points": 3,
                "description": "Returns the supported compound dry-heat, fire-weather, and exposure label with a score of 6.",
                "partial_credit": "Award partial credit for the right label with one arithmetic slip or the right score with an unclear label.",
            },
            {
                "name": "heat_accumulation_metrics",
                "points": 4,
                "description": "Computes heat load as 36.9 C-days within +/-0.2 and counts 5 warm nights.",
                "partial_credit": "Award partial credit for one correct metric or correct formulas with minor rounding errors.",
            },
            {
                "name": "dry_air_and_humidity_screens",
                "points": 4,
                "description": "Computes peak VPD as 7.62 kPa within +/-0.05, 75 hot-dry hours within +/-1, and 0 hot-humid hours.",
                "partial_credit": "Award partial credit for two of the three values or correct screen logic with a small threshold mistake.",
            },
            {
                "name": "exposure_ledger",
                "points": 3,
                "description": "Reports population about 344,722 within +/-100 and 81 critical amenities, with the exposure test passed.",
                "partial_credit": "Award partial credit for one correct exposure value or a pass state without both anchors.",
            },
            {
                "name": "threshold_arithmetic_and_rejection",
                "points": 4,
                "description": "Marks all six tests as passed, maps score 6 to the final label, and rejects humid-heat and single-peak framings from the ledger.",
                "partial_credit": "Award partial credit for a mostly correct pass ledger with one missing countercheck.",
            },
            {
                "name": "json_structure_and_rounding",
                "points": 2,
                "description": "Uses compact JSON with the requested keys and specified rounding.",
                "partial_credit": "Award partial credit for readable JSON with minor key-name or rounding deviations.",
            },
        ],
    }

    return {
        "schema_version": "1.0",
        "task_id": TASK_ID,
        "event_id": EVENT_ID,
        "task_type": "short_answer",
        "target_family": "compound_dry_heat_fire_weather_exposure_diagnosis",
        "evaluation_mode": "hybrid",
        "difficulty_level": "L3",
        "primary_gt": primary_gt,
        "key_values": {
            "event_name": event["event_name"],
            "event_window": {
                "start": dates[0],
                "end": dates[-1],
                "days": len(dates),
            },
            "thresholds": thresholds,
            "computed_values": {
                "heat_load_c_days_gt35": heat_load,
                "warm_nights_ge18c": warm_nights,
                "peak_vpd_kpa": peak_vpd,
                "hot_dry_hours": int(hot_dry_hours),
                "hot_humid_hours": int(hot_humid_hours),
                "population": population,
                "critical_amenities": int(critical_amenities),
            },
            "test_passes": tests,
            "tolerances": {
                "heat_load_c_days_gt35": 0.2,
                "peak_vpd_kpa": 0.05,
                "hot_dry_hours": 1,
                "population": 100,
            },
        },
        "decision_rule": {
            "score_per_passed_test": 1,
            "labels": {
                "score_5_to_6": "compound_dry_heat_fire_weather_exposure_supported",
                "score_3_to_4": "partial_support",
                "score_0_to_2": "not_supported",
            },
        },
        "rubric": rubric,
        "provenance": {
            "computed_by": "compute_gt.py",
            "source_package_id": EVENT_ID,
            "source_files": [event_rel, met_rel, pop_rel, amenity_rel],
        },
    }


def main() -> None:
    output = compute()
    apply_deepened_task_frame(output)
    (Path(__file__).resolve().parent / OUTPUT_NAME).write_text(
        json.dumps(output, indent=2, ensure_ascii=True) + "\n",
        encoding="utf-8",
    )


if __name__ == "__main__":
    main()
